#!/usr/bin/env node
/**
 * Records the last commit date of each service page into
 * src/lib/service-updates.ts, so the "Page updated" line shown on every
 * service page stays honest and reproducible. Run after editing service
 * pages; the generated file is committed with the pages it describes.
 */
import { execSync } from 'node:child_process';
import { readdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const pagesDir = path.resolve('src/app/(en)');
const pageFiles = [];

function walk(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full);
    else if (entry.name === 'page.tsx' && !full.includes('/app/(en)/app/')) {
      pageFiles.push(full);
    }
  }
}

walk(pagesDir);

const updates = {};
for (const file of pageFiles) {
  const rel = path.relative(process.cwd(), file);
  let date = null;
  try {
    date = execSync(`git log -1 --format=%cs -- "${rel}"`)
      .toString()
      .trim();
  } catch {
    date = null;
  }
  if (!date) continue;
  const route = rel
    .replace(/^src\/app\/\(en\)/, '')
    .replace(/\/page\.tsx$/, '')
    .replace(/^\/?$/, '/');
  updates[route] = date;
}

const body = `/**
 * Last commit date per service page, generated by scripts/record-page-updates.mjs.
 * Regenerate (and commit) whenever service page content changes, so the
 * "Page updated" line stays accurate.
 */
export const SERVICE_UPDATES: Record<string, string> = ${JSON.stringify(updates, null, 2)};
`;

writeFileSync(path.resolve('src/lib/service-updates.ts'), body);
console.log(`recorded ${Object.keys(updates).length} pages`);
